from typing import List

def printAllPalindromes(s: str) -> List[str]:
    n = len(s)
    found = []  # (起点, 长度)
    for c in range(n):
        for l, r in ((c, c), (c, c + 1)):  # 奇数中心、偶数中心
            while l >= 0 and r < n and s[l] == s[r]:
                if r - l + 1 >= 3:
                    found.append((l, r - l + 1))
                l -= 1
                r += 1
    found.sort()  # 按出现位置输出
    return [s[i:i + k] for i, k in found]

if __name__ == "__main__":
    for p in printAllPalindromes(input().strip()):
        print(p)
